TEMPLATE = "import numpy as np\n\nBG = __BG__\n\n\ndef _components(mask):\n    remaining = set(map(tuple, np.argwhere(mask)))\n    groups = []\n    while remaining:\n        todo = [remaining.pop()]; cells = set(todo)\n        while todo:\n            r, c = todo.pop()\n            for dr in (-1, 0, 1):\n                for dc in (-1, 0, 1):\n                    point = (r+dr, c+dc)\n                    if point in remaining:\n                        remaining.remove(point); cells.add(point); todo.append(point)\n        groups.append(cells)\n    return groups\n\n\ndef _interpret(grid, frame):\n    g = np.asarray(grid, dtype=int)\n    yy, xx = np.nonzero(g == frame)\n    top, bottom, left, right = int(yy.min()), int(yy.max()), int(xx.min()), int(xx.max())\n    h, w = bottom-top+1, right-left+1\n    if min(h,w) < 3: raise ValueError('Frame too small')\n    box = g[top:bottom+1, left:right+1]\n    if not (np.all(box[0,:] == frame) and np.all(box[-1,:] == frame)\n            and np.all(box[:,0] == frame) and np.all(box[:,-1] == frame)\n            and np.all((box == frame) | (box == BG))):\n        raise ValueError('Not a frame with holes')\n    gallery = (g != BG) & (g != frame)\n    sy, sx = np.nonzero(gallery)\n    if not len(sy):raise ValueError('No gallery')\n    sides=[]\n    if np.all(sx > right):sides.append((0,w,0))\n    if np.all(sx < left):sides.append((0,-w,0))\n    if np.all(sy > bottom):sides.append((h,0,1))\n    if np.all(sy < top):sides.append((-h,0,1))\n    if len(sides)!=1:raise ValueError('Gallery side ambiguous')\n    dy,dx,axis=sides[0]\n    def aligned(cells):\n        offset=min(p[axis] for p in cells)\n        return frozenset((r-offset,c) if axis==0 else (r,c-offset) for r,c in cells)\n    matches={}\n    for colour in np.unique(g[gallery]):\n        cells={(int(r)-top-dy,int(c)-left-dx) for r,c in np.argwhere(g==colour)}\n        key=aligned(cells)\n        matches.setdefault(key,set()).add(int(colour))\n    result=box.copy()\n    holes=_components(box==BG)\n    if not holes:raise ValueError('No holes')\n    for hole in holes:\n        choices=matches.get(aligned(hole),set())\n        if len(choices)!=1:raise ValueError('No unique position-preserving match')\n        for r,c in hole:result[r,c]=next(iter(choices))\n    return result.tolist()\n\n\ndef _answer(grid):\n    answers=set()\n    for colour in np.unique(np.asarray(grid,dtype=int)):\n        if colour==BG:continue\n        try:ans=_interpret(grid,int(colour))\n        except ValueError:continue\n        answers.add(tuple(map(tuple,ans)))\n    if len(answers)!=1:raise ValueError('No unique visible frame/gallery solution')\n    return [list(row) for row in next(iter(answers))]\n\n\ndef solve(demonstrations, grid):\n    if not demonstrations:raise ValueError('Demonstrations required')\n    for demo in demonstrations:\n        if _answer(demo['input'])!=demo['output']:raise ValueError('Demo violates aligned shape matching')\n    return _answer(grid)\n"

def build_program(d4, palette):
    return TEMPLATE.replace("__BG__", str(int(palette[0])))
